import type { Metadata } from "next";
import Link from "next/link";
import tokenData from "@/core/ui/design-system/schema/token-data.json";
import { TokenStudio, type TokenRecord } from "@/core/ui/design-system/token-studio";

export const metadata: Metadata = {
  title: "Bộ token thiết kế",
  description: "Danh mục token, giá trị theo giao diện sáng/tối và kiểm tra tương phản AA.",
};

/**
 * The catalogue is generated by scripts/build-tokens.mjs, so this page never
 * restates a value: it reads the same artefact the CSS is built from.
 */
export default function Page() {
  /* Numeric tokens (line heights, weights) arrive as numbers; the table renders text. */
  const tokens: TokenRecord[] = tokenData.catalog.map((token) => ({
    name: token.name,
    layer: token.layer,
    category: token.category,
    type: token.type,
    value: String(token.value),
    light: String(token.light),
    dark: String(token.dark),
    description: token.description,
  }));

  return (
    <div className="page">
      <header className="page-header">
        <div className="stack gap-2">
          <p className="page-eyebrow">Thư viện</p>
          <h1>Bộ token thiết kế</h1>
          <p className="page-lede">
            Ba lớp nguyên thuỷ → ngữ nghĩa → thành phần. Thành phần chỉ tham chiếu ngữ
            nghĩa, không bao giờ gắn cứng một mã màu.
          </p>
        </div>
        <div className="page-actions">
          <Link className="btn btn-ghost" href="/design-system">
            Xem thành phần
          </Link>
        </div>
      </header>

      <TokenStudio
        tokens={tokens}
        contrast={tokenData.contrast}
        profiles={Object.keys(tokenData.profiles)}
        version={tokenData.version}
      />

      <p className="page-footnote">
        Giá trị trên trang này đọc từ token-data.json do npm run tokens:build sinh ra. Sửa
        tokens/source.json rồi build lại — không chỉnh tay tokens.css.
      </p>
    </div>
  );
}
